/**
 * argparse.mjs
 *
 * A faithful, dependency-free port of the slice of CPython's ``argparse`` that
 * test17.py exercises.  The reference binary is a PyInstaller bundle of
 * CPython 3.12 (the ``-hx`` short-option-chaining behaviour pins it at
 * 3.12.5+), so the algorithms below mirror that exact source revision:
 *
 *   - ``ArgumentParser._parse_known_args``   (two-pass O/A token classifier)
 *   - ``ArgumentParser._parse_optional``     (exact match, "=" form, abbrev)
 *   - ``ArgumentParser._get_option_tuples``  (prefix matching / ambiguity)
 *   - ``ArgumentParser._match_argument``     (nargs regex, "--" is not a value)
 *   - ``ArgumentParser._get_values``         ("--" is stripped for positionals
 *                                             only, since 3.12.5)
 *   - ``HelpFormatter``                      (usage line + options section)
 *
 * Everything is written against plain JS strings and arrays; the only import
 * is the local Python-repr helper used to quote values inside the
 * "invalid choice" diagnostic exactly the way ``%r`` does.
 */

import { pyReprString } from './pyrepr.mjs';

// ---------------------------------------------------------------------------
// Constants mirroring argparse's module-level defaults
// ---------------------------------------------------------------------------

/** ``ArgumentParser(prefix_chars='-')`` — the only prefix we support. */
const PREFIX_CHARS = '-';

/** ``argparse.SUPPRESS`` — a default of this value keeps a dest out of the namespace. */
const SUPPRESS = '==SUPPRESS==';

/** ``HelpFormatter(max_help_position=24)``. */
const MAX_HELP_POSITION = 24;

/**
 * ``shutil.get_terminal_size().columns - 2``.  Python falls back to 80 columns
 * whenever COLUMNS is unset and stdout is not a terminal, which is how the
 * reference binary is measured, so the width is pinned rather than sniffed.
 */
const HELP_WIDTH = 80 - 2;

/** ``ArgumentParser._negative_number_matcher``. */
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

// ---------------------------------------------------------------------------
// Internal error type — mirrors argparse.ArgumentError
// ---------------------------------------------------------------------------

/**
 * Raised while parsing; ``parseArgs`` catches it and turns it into the
 * standard "argument <name>: <message>" diagnostic.
 */
class ArgumentError extends Error {
  /**
   * @param {string|null} argumentName pre-formatted action name ("-h/--help")
   * @param {string} message the human readable failure
   */
  constructor(argumentName, message) {
    super(argumentName === null ? message : `argument ${argumentName}: ${message}`);
    this.name = 'ArgumentError';
    this.argumentName = argumentName;
    this.rawMessage = message;
  }
}

// ---------------------------------------------------------------------------
// Type converters
// ---------------------------------------------------------------------------

/** Identity converter — matches ``type=str`` on an already-string argv token. */
function strConverter(value) {
  return String(value);
}
strConverter.typeName = 'str';

/** ``int(value)`` with argparse's strictness (no partial parses). */
function intConverter(value) {
  const text = String(value).trim();
  if (!/^[+-]?\d+$/.test(text)) {
    throw new RangeError('invalid literal');
  }
  return Number(text);
}
intConverter.typeName = 'int';

/** ``float(value)``. */
function floatConverter(value) {
  const text = String(value).trim();
  if (text === '' || !Number.isFinite(Number(text))) {
    throw new RangeError('invalid literal');
  }
  return Number(text);
}
floatConverter.typeName = 'float';

/**
 * Normalises the ``type`` option of addArgument into a callable carrying a
 * ``typeName`` used by the "invalid X value" diagnostic.
 *
 * @param {Function|string|null|undefined} type
 * @returns {Function}
 */
function resolveType(type) {
  if (type === null || type === undefined) return strConverter;
  if (typeof type === 'function') {
    if (type === String) return strConverter;
    if (type === Number) return floatConverter;
    if (!type.typeName) type.typeName = type.name || 'type';
    return type;
  }
  switch (String(type)) {
    case 'str':
    case 'string':
      return strConverter;
    case 'int':
      return intConverter;
    case 'float':
      return floatConverter;
    default:
      return strConverter;
  }
}

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

/**
 * One registered optional argument.  Only the two actions the script needs
 * ('store' and 'help') exist; ``nargs`` is ``null`` for store (exactly one
 * value) and ``0`` for help.
 */
class Action {
  constructor({
    optionStrings,
    dest,
    nargs = null,
    kind = 'store',
    type = null,
    required = false,
    choices = null,
    help = null,
    metavar = null,
    defaultValue = null,
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.kind = kind;
    this.type = resolveType(type);
    this.required = required;
    this.choices = choices;
    this.help = help;
    this.metavar = metavar;
    this.defaultValue = defaultValue;
  }
}

/**
 * ``argparse._get_action_name`` — how an action is named inside error text.
 * For optionals it is every option string joined with "/", e.g. "-h/--help".
 *
 * @param {Action} action
 * @returns {string}
 */
function actionName(action) {
  return action.optionStrings.join('/');
}

// ---------------------------------------------------------------------------
// Small text helpers
// ---------------------------------------------------------------------------

/** Pads ``text`` on the right with spaces until it is ``width`` wide. */
function padRight(text, width) {
  return text.length >= width ? text : text + ' '.repeat(width - text.length);
}

/**
 * Greedy word wrap, matching ``textwrap.wrap`` closely enough for help text
 * (whitespace collapsed, never breaks a long word apart).
 *
 * @param {string} text
 * @param {number} width
 * @returns {string[]}
 */
function wrapText(text, width) {
  const words = text.split(/\s+/).filter((word) => word.length > 0);
  if (words.length === 0) return [];
  const lines = [];
  let current = words[0];
  for (let i = 1; i < words.length; i += 1) {
    const word = words[i];
    if (current.length + 1 + word.length <= width) {
      current += ` ${word}`;
    } else {
      lines.push(current);
      current = word;
    }
  }
  lines.push(current);
  return lines;
}

// ---------------------------------------------------------------------------
// ArgumentParser
// ---------------------------------------------------------------------------

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean, allowAbbrev?: boolean}} [options]
   *   ``prog`` defaults to the reference binary's name so every byte written to
   *   stdout/stderr matches it.
   */
  constructor({ prog = 'test17_executable', addHelp = true, allowAbbrev = true } = {}) {
    this.prog = prog;
    this.allowAbbrev = allowAbbrev;

    /** @type {Action[]} registration order drives usage/help/required order */
    this._actions = [];
    /** @type {Map<string, Action>} insertion-ordered, like Python's dict */
    this._optionStringActions = new Map();
    /** ``_has_negative_number_optionals`` — true if an option looks like -1 */
    this._hasNegativeNumberOptionals = false;

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        dest: 'help',
        defaultValue: SUPPRESS,
        help: 'show this help message and exit',
      });
    }
  }

  // -------------------------------------------------------------------------
  // Registration
  // -------------------------------------------------------------------------

  /**
   * Registers an optional argument.
   *
   * @param {string|string[]} optionStrings e.g. '--data' or ['-d', '--data']
   * @param {{type?: any, required?: boolean, choices?: any[], help?: string,
   *          dest?: string, metavar?: string, action?: string,
   *          defaultValue?: any, nargs?: number|null}} [options]
   * @returns {Action}
   */
  addArgument(optionStrings, options = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings.slice() : [optionStrings];
    if (strings.length === 0) {
      throw new Error('addArgument requires at least one option string');
    }
    for (const optionString of strings) {
      if (!PREFIX_CHARS.includes(optionString.charAt(0))) {
        // Positional arguments are intentionally out of scope: the script the
        // reference binary was built from declares none.
        throw new Error(`positional arguments are not supported: ${optionString}`);
      }
    }

    const {
      type = null,
      required = false,
      choices = null,
      help = null,
      metavar = null,
      action: kind = 'store',
      defaultValue = null,
      nargs,
    } = options;

    // ``_get_optional_kwargs``: '--foo-bar' -> 'foo_bar', else '-x' -> 'x'.
    let dest = options.dest;
    if (dest === undefined || dest === null) {
      const longOption = strings.find((s) => s.length > 1 && PREFIX_CHARS.includes(s.charAt(1)));
      const source = longOption !== undefined ? longOption : strings[0];
      dest = source.replace(/^[-]+/, '').replace(/-/g, '_');
    }

    const resolvedNargs = nargs !== undefined ? nargs : kind === 'help' ? 0 : null;

    const registered = new Action({
      optionStrings: strings,
      dest,
      nargs: resolvedNargs,
      kind,
      type,
      required,
      choices,
      help,
      metavar,
      defaultValue,
    });

    this._actions.push(registered);
    for (const optionString of strings) {
      this._optionStringActions.set(optionString, registered);
      if (NEGATIVE_NUMBER_RE.test(optionString)) {
        this._hasNegativeNumberOptionals = true;
      }
    }
    return registered;
  }

  // -------------------------------------------------------------------------
  // Help / usage formatting  (HelpFormatter)
  // -------------------------------------------------------------------------

  /**
   * ``HelpFormatter._metavar_formatter`` — explicit metavar wins, then choices
   * rendered as {a,b}, then the fallback (dest upper-cased for optionals).
   *
   * @param {Action} action
   * @returns {string}
   */
  _metavarFor(action) {
    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
    if (action.choices !== null && action.choices !== undefined) {
      return `{${action.choices.map((choice) => String(choice)).join(',')}}`;
    }
    return action.dest.toUpperCase();
  }

  /**
   * ``HelpFormatter._format_action_invocation`` — the left-hand column of the
   * options list: "-h, --help" for zero-arg actions, "--data DATA" otherwise.
   *
   * @param {Action} action
   * @returns {string}
   */
  _formatActionInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    const args = this._metavarFor(action);
    return action.optionStrings.map((optionString) => `${optionString} ${args}`).join(', ');
  }

  /**
   * ``HelpFormatter._format_actions_usage`` for a single action: only the first
   * option string appears, and non-required actions are bracketed.
   *
   * @param {Action} action
   * @returns {string}
   */
  _formatUsagePart(action) {
    const optionString = action.optionStrings[0];
    const part = action.nargs === 0 ? optionString : `${optionString} ${this._metavarFor(action)}`;
    return action.required ? part : `[${part}]`;
  }

  /**
   * @returns {string} "usage: <prog> [-h] --data DATA --verify_iat {true,false}\n"
   */
  formatUsage() {
    const parts = this._actions.map((action) => this._formatUsagePart(action));
    const tail = parts.length > 0 ? ` ${parts.join(' ')}` : '';
    return `usage: ${this.prog}${tail}\n`;
  }

  /**
   * @returns {string} the full ``--help`` text, terminated by exactly one \n
   */
  formatHelp() {
    // ``HelpFormatter.add_argument`` tracks the widest invocation (+ the 2
    // space section indent) to decide where the help column starts.
    const indent = 2;
    let actionMaxLength = 0;
    for (const action of this._actions) {
      if (action.help === SUPPRESS) continue;
      actionMaxLength = Math.max(
        actionMaxLength,
        this._formatActionInvocation(action).length + indent,
      );
    }
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const helpTextWidth = Math.max(HELP_WIDTH - helpPosition, 11);
    const actionWidth = helpPosition - indent - 2;

    const lines = [];
    for (const action of this._actions) {
      if (action.help === SUPPRESS) continue;
      const invocation = this._formatActionInvocation(action);

      if (!action.help) {
        // No help text: the line ends right after the invocation, no padding.
        lines.push(' '.repeat(indent) + invocation);
        continue;
      }

      const helpLines = wrapText(action.help, helpTextWidth);
      if (invocation.length <= actionWidth) {
        // Short invocation: help starts on the same line at ``helpPosition``.
        const header = ' '.repeat(indent) + padRight(invocation, actionWidth) + '  ';
        lines.push(header + (helpLines.length > 0 ? helpLines[0] : ''));
        for (let i = 1; i < helpLines.length; i += 1) {
          lines.push(' '.repeat(helpPosition) + helpLines[i]);
        }
      } else {
        // Long invocation: it gets its own line, help is indented below it.
        lines.push(' '.repeat(indent) + invocation);
        for (const helpLine of helpLines) {
          lines.push(' '.repeat(helpPosition) + helpLine);
        }
      }
    }

    let text = this.formatUsage();
    if (lines.length > 0) {
      text += `\noptions:\n${lines.join('\n')}\n`;
    }
    // ``HelpFormatter.format_help`` collapses runs of blank lines and then
    // normalises to a single trailing newline.
    text = text.replace(/\n\n\n+/g, '\n\n');
    return `${text.replace(/^\n+/, '').replace(/\n+$/, '')}\n`;
  }

  // -------------------------------------------------------------------------
  // Exiting
  // -------------------------------------------------------------------------

  /** Writes the help text to stdout and exits 0, like argparse's help action. */
  exitWithHelp() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  /**
   * ``ArgumentParser.error`` — usage plus "<prog>: error: <message>" on stderr,
   * then exit status 2.
   *
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  // -------------------------------------------------------------------------
  // Option-string recognition
  // -------------------------------------------------------------------------

  /**
   * ``ArgumentParser._get_option_tuples`` — every registered option string the
   * token could be an abbreviation of.
   *
   * @param {string} optionString
   * @returns {Array<[Action, string, string|null, string|null]>}
   */
  _getOptionTuples(optionString) {
    const result = [];
    const first = optionString.charAt(0);
    const second = optionString.charAt(1);

    if (PREFIX_CHARS.includes(first) && PREFIX_CHARS.includes(second)) {
      // "--" style: only ever split at the '='.
      if (this.allowAbbrev) {
        const eq = optionString.indexOf('=');
        const optionPrefix = eq === -1 ? optionString : optionString.slice(0, eq);
        const sep = eq === -1 ? null : '=';
        const explicitArg = eq === -1 ? null : optionString.slice(eq + 1);
        for (const [candidate, action] of this._optionStringActions) {
          if (candidate.startsWith(optionPrefix)) {
            result.push([action, candidate, sep, explicitArg]);
          }
        }
      }
    } else if (PREFIX_CHARS.includes(first) && !PREFIX_CHARS.includes(second)) {
      // "-x" style: a single-character option may carry its value inline.
      const optionPrefix = optionString;
      const shortOptionPrefix = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);
      for (const [candidate, action] of this._optionStringActions) {
        if (candidate === shortOptionPrefix) {
          result.push([action, candidate, '', shortExplicitArg]);
        } else if (candidate.startsWith(optionPrefix)) {
          result.push([action, candidate, null, null]);
        }
      }
    } else {
      this.error(`unexpected option string: ${optionString}`);
    }

    return result;
  }

  /**
   * ``ArgumentParser._parse_optional`` — decide whether a token is an option.
   *
   * @param {string} argString
   * @returns {[Action|null, string, string|null, string|null]|null}
   *   null means "this is a positional-looking token"; a tuple whose first
   *   element is null means "an option we do not know about".
   */
  _parseOptional(argString) {
    // An empty string was meant to be a positional.
    if (argString === '') return null;

    // Anything not starting with a prefix char is a positional.
    if (!PREFIX_CHARS.includes(argString.charAt(0))) return null;

    // Exact match wins immediately.
    if (this._optionStringActions.has(argString)) {
      return [this._optionStringActions.get(argString), argString, null, null];
    }

    // A lone "-" was meant to be positional.
    if (argString.length === 1) return null;

    // "--opt=value" where the part before "=" is a known option.
    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      if (this._optionStringActions.has(optionString)) {
        return [
          this._optionStringActions.get(optionString),
          optionString,
          '=',
          argString.slice(eq + 1),
        ];
      }
    }

    // Abbreviations / inline short-option values.
    const optionTuples = this._getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const matches = optionTuples.map((tuple) => tuple[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }

    // Looks like a negative number and no option string does: positional.
    if (NEGATIVE_NUMBER_RE.test(argString) && !this._hasNegativeNumberOptionals) {
      return null;
    }

    // Contains a space: positional.
    if (argString.includes(' ')) return null;

    // An unknown option string.
    return [null, argString, null, null];
  }

  // -------------------------------------------------------------------------
  // nargs matching
  // -------------------------------------------------------------------------

  /**
   * ``HelpFormatter``-free version of ``_get_nargs_pattern``.  For optionals
   * every '-' placeholder is stripped, which is precisely why "--" can never
   * be swallowed as an option's value.
   *
   * @param {Action} action
   * @returns {string}
   */
  _getNargsPattern(action) {
    let pattern;
    if (action.nargs === null || action.nargs === undefined) {
      pattern = '(-*A-*)';
    } else {
      pattern = `(-*${'A'.repeat(action.nargs).split('').join('-*')}-*)`;
    }
    if (action.optionStrings.length > 0) {
      pattern = pattern.split('-*').join('').split('-').join('');
    }
    return pattern;
  }

  /**
   * ``ArgumentParser._match_argument`` — how many following tokens this action
   * consumes, given the O/A pattern of what comes next.
   *
   * @param {Action} action
   * @param {string} patternString
   * @returns {number}
   */
  _matchArgument(action, patternString) {
    const nargsPattern = this._getNargsPattern(action);
    const match = new RegExp(`^${nargsPattern}`).exec(patternString);
    if (match === null) {
      let message;
      if (action.nargs === null || action.nargs === undefined) {
        message = 'expected one argument';
      } else if (action.nargs === 1) {
        message = 'expected 1 argument';
      } else {
        message = `expected ${action.nargs} arguments`;
      }
      throw new ArgumentError(actionName(action), message);
    }
    return match[1].length;
  }

  // -------------------------------------------------------------------------
  // Value conversion / validation
  // -------------------------------------------------------------------------

  /**
   * ``ArgumentParser._get_value`` — run the action's type converter.
   *
   * @param {Action} action
   * @param {string} argString
   */
  _getValue(action, argString) {
    try {
      return action.type(argString);
    } catch (error) {
      const typeName = action.type.typeName || 'value';
      throw new ArgumentError(
        actionName(action),
        `invalid ${typeName} value: ${pyReprString(argString)}`,
      );
    }
  }

  /**
   * ``ArgumentParser._check_value`` — enforce ``choices``.
   *
   * @param {Action} action
   * @param {*} value
   */
  _checkValue(action, value) {
    if (action.choices !== null && action.choices !== undefined && !action.choices.includes(value)) {
      const choices = action.choices.map((choice) => pyReprString(String(choice))).join(', ');
      throw new ArgumentError(
        actionName(action),
        `invalid choice: ${pyReprString(String(value))} (choose from ${choices})`,
      );
    }
  }

  /**
   * ``ArgumentParser._get_values``.  Note that since CPython 3.12.5 the leading
   * "--" is stripped for positionals only, so ``--data=--`` really does yield
   * the string "--".
   *
   * @param {Action} action
   * @param {string[]} argStrings
   */
  _getValues(action, argStrings) {
    if (argStrings.length === 1 && (action.nargs === null || action.nargs === undefined)) {
      const value = this._getValue(action, argStrings[0]);
      this._checkValue(action, value);
      return value;
    }
    const values = argStrings.map((argString) => this._getValue(action, argString));
    for (const value of values) this._checkValue(action, value);
    return values;
  }

  // -------------------------------------------------------------------------
  // Parsing
  // -------------------------------------------------------------------------

  /**
   * Parses argv and returns a namespace object, exiting the process on any
   * error exactly the way argparse does.
   *
   * @param {string[]} [argv] argv without the interpreter and script path
   * @returns {Object<string, *>}
   */
  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /**
   * ``ArgumentParser.parse_known_args`` — like parseArgs but returns the
   * leftover tokens instead of complaining about them.
   *
   * @param {string[]} [argv]
   * @returns {[Object<string, *>, string[]]}
   */
  parseKnownArgs(argv) {
    const args = argv === undefined || argv === null ? process.argv.slice(2) : argv.slice();
    try {
      return this._parseKnownArgs(args);
    } catch (error) {
      if (error instanceof ArgumentError) {
        this.error(error.message);
      }
      throw error;
    }
  }

  /**
   * The heart of ``ArgumentParser._parse_known_args``.
   *
   * @param {string[]} argStrings
   * @returns {[Object<string, *>, string[]]}
   */
  _parseKnownArgs(argStrings) {
    // --- namespace defaults -------------------------------------------------
    const namespace = {};
    for (const action of this._actions) {
      if (action.defaultValue !== SUPPRESS) {
        namespace[action.dest] = action.defaultValue;
      }
    }

    // --- pass 1: classify every token as an Option or an Argument -----------
    // A literal "--" is recorded as '-' and forces everything after it to 'A',
    // which is what makes "--data -- x" fail instead of consuming "--".
    const pattern = [];
    /** @type {Map<number, [Action|null, string, string|null, string|null]>} */
    const optionTuples = new Map();
    let sawDoubleDash = false;
    for (let i = 0; i < argStrings.length; i += 1) {
      const argString = argStrings[i];
      if (sawDoubleDash) {
        pattern.push('A');
        continue;
      }
      if (argString === '--') {
        pattern.push('-');
        sawDoubleDash = true;
        continue;
      }
      const optionTuple = this._parseOptional(argString);
      if (optionTuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, optionTuple);
        pattern.push('O');
      }
    }
    const patternString = pattern.join('');

    // --- pass 2: consume options left to right ------------------------------
    /** @type {string[]} */
    const extras = [];
    /** @type {Set<Action>} */
    const seenActions = new Set();

    /**
     * ``take_action`` — convert, validate and store one action's values.
     *
     * @param {Action} action
     * @param {string[]} values
     * @param {string} optionString
     */
    const takeAction = (action, values, optionString) => {
      seenActions.add(action);
      const argumentValues = this._getValues(action, values);
      if (action.kind === 'help') {
        this.exitWithHelp();
        return;
      }
      namespace[action.dest] = argumentValues;
    };

    /**
     * ``consume_optional`` — handle the option at ``startIndex`` plus whatever
     * follows it, returning the index to continue from.
     *
     * @param {number} startIndex
     * @returns {number}
     */
    const consumeOptional = (startIndex) => {
      let [action, optionString, sep, explicitArg] = optionTuples.get(startIndex);
      /** @type {Array<[Action, string[], string]>} */
      const actionTuples = [];
      let stop = startIndex + 1;

      for (;;) {
        // Unknown option: hand it to the caller as an extra.
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null && explicitArg !== undefined) {
          const argCount = this._matchArgument(action, 'A');

          // A single-dash zero-arg option may be followed by more options
          // packed into the same token ("-hx" behaves like "-h x").
          if (
            argCount === 0 &&
            !PREFIX_CHARS.includes(optionString.charAt(1)) &&
            explicitArg !== ''
          ) {
            if (sep || PREFIX_CHARS.includes(explicitArg.charAt(0))) {
              throw new ArgumentError(
                actionName(action),
                `ignored explicit argument ${pyReprString(explicitArg)}`,
              );
            }
            actionTuples.push([action, [], optionString]);
            const char = optionString.charAt(0);
            optionString = char + explicitArg.charAt(0);
            if (this._optionStringActions.has(optionString)) {
              action = this._optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (explicitArg === '') {
                sep = null;
                explicitArg = null;
              } else if (explicitArg.charAt(0) === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
            } else {
              extras.push(char + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ArgumentError(
              actionName(action),
              `ignored explicit argument ${pyReprString(explicitArg)}`,
            );
          }
        } else {
          // No inline value: pull the required count from the following tokens.
          const start = startIndex + 1;
          const selectedPatterns = patternString.slice(start);
          const argCount = this._matchArgument(action, selectedPatterns);
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
          break;
        }
      }

      for (const [tupleAction, tupleArgs, tupleOptionString] of actionTuples) {
        takeAction(tupleAction, tupleArgs, tupleOptionString);
      }
      return stop;
    };

    // There are no positional actions in this parser, so any token that is not
    // consumed by an option — including "--" and everything after it — is an
    // extra, collected in argv order.
    let index = 0;
    while (index < argStrings.length) {
      if (optionTuples.has(index)) {
        index = consumeOptional(index);
      } else {
        extras.push(argStrings[index]);
        index += 1;
      }
    }

    // --- required arguments are reported before unrecognized ones -----------
    const requiredActions = [];
    for (const action of this._actions) {
      if (!seenActions.has(action) && action.required) {
        requiredActions.push(actionName(action));
      }
    }
    if (requiredActions.length > 0) {
      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
    }

    return [namespace, extras];
  }
}

export default ArgumentParser;

// Scratch stub of pyrepr.mjs used only to exercise argparse.mjs in isolation.
// The real module is written by another agent; this mirrors CPython's
// str.__repr__ closely enough for the argparse diagnostics.

const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

export function pyIsPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function hex(n, width) {
  return n.toString(16).padStart(width, '0');
}

export function pyReprString(str) {
  const hasSingle = str.includes("'");
  const hasDouble = str.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (!pyIsPrintable(ch)) {
      if (cp < 0x100) out += '\\x' + hex(cp, 2);
      else if (cp < 0x10000) out += '\\u' + hex(cp, 4);
      else out += '\\U' + hex(cp, 8);
    } else out += ch;
  }
  return out + quote;
}

